14	// 本文件为“提交入口先保存成功、才登记作业与非空请求号”这一行为补充回归
15	// 保障。合法请求（非空整数序列、合法种子与依赖、上游已成功并有完整归档）
16	// 在首份记录无法保存时必须被当作未接受：返回实际保存错误而非作业视图，
17	// 不占用作业号与请求号、不留正式记录、不影响已有作业；写入恢复后同一
18	// 提交人+请求号仍可原样重试或改交另一份合法内容。幂等规则只在请求真正
19	// 被接受以后生效——已接受作业后来计算失败不构成重建作业的理由。
20	
21	// countTmpFiles 统计目录中原子写残留的临时记录数（保存失败时 writeFileAtomic
22	// 必须自行清理，不得把临时文件留在目录中）。
23	func countTmpFiles(t *testing.T, dir string) int {
24		t.Helper()
25		entries, err := os.ReadDir(dir)
26		if err != nil {
27			t.Fatal(err)
28		}
29		n := 0
30		for _, e := range entries {
31			if !e.IsDir() && strings.HasPrefix(e.Name(), ".tmp-") {
32				n++
33			}
34		}
35		return n
36	}
37	
38	// blockRenameWithDir 在目标正式记录路径放置一个非空目录，使“临时记录已
39	// 写好、却无法 rename 为正式记录”真实发生：临时文件仍可在归档目录中创建
40	// 和写盘，但替换目标被非空目录挡住（即便以 root 运行 rename 仍失败）。
41	// 返回清理函数。
42	func blockRenameWithDir(t *testing.T, dir string, id uint64) func() {
43		t.Helper()
44		target := filepath.Join(dir, jobFileName(id))
45		if err := os.Mkdir(target, 0o700); err != nil {
46			t.Fatalf("mkdir rename blocker: %v", err)
47		}
48		if err := os.WriteFile(filepath.Join(target, "keep"), []byte("x"), 0o600); err != nil {
49			t.Fatal(err)
50		}
51		return func() { _ = os.RemoveAll(target) }
52	}
53	
54	// isRenameBlockedError 判断错误是否为 rename 到非空目录时的实际保存错误。
55	// Linux 对“文件 rename 到已存在的非空目录”返回 EEXIST（空目录则为 EISDIR）。
56	func isRenameBlockedError(err error) bool {
57		return errors.Is(err, fs.ErrExist) ||
58			errors.Is(err, syscall.ENOTEMPTY) || errors.Is(err, syscall.EISDIR)
59	}
60	
61	// 上游：总和为 5 的成功归档；本文件各用例在它之后提交依赖它的新作业。
62	func submitSumFiveUpstream(t *testing.T, s *Store) *Job {
63		t.Helper()
64		up := mustSubmit(t, s, SubmitRequest{
65			Submitter: "alice", RequestID: "up", Values: []int64{5},
66		})
67		got := waitStatus(t, s, up.ID, StatusSucceeded)
68		if got.Archive == nil || got.Archive.Sum != 5 || got.Archive.SumOfSquares != 25 {
69			t.Fatalf("upstream archive wrong: %+v", got)
70		}
71		if len(got.Archive.EffectiveValues) != 1 || got.Archive.EffectiveValues[0] != 5 {
72			t.Fatalf("upstream effective=%v want [5]", got.Archive.EffectiveValues)
73		}
74		return got
75	}
76	
77	// assertUpstreamUnchanged 断言已有上游作业的参数、状态与成功归档在一次失败
78	// 提交前后完全保持原样（含逐字节落盘记录），不会仅因下游提交保存失败而
79	// 变成失败或取消。
80	func assertUpstreamUnchanged(t *testing.T, dir string, s *Store, up *Job, diskBefore []byte) {
81		t.Helper()
82		g, err := s.Get(up.ID)
83		if err != nil {
84			t.Fatal(err)
85		}
86		if g.Status != StatusSucceeded || g.BlockerID != 0 || g.Archive == nil {
87			t.Fatalf("upstream disturbed: status=%s blocker=%d archive=%v",
88				g.Status, g.BlockerID, g.Archive)
89		}
90		if g.Archive.Sum != 5 || g.Archive.SumOfSquares != 25 ||
91			g.Archive.Checksum != up.Archive.Checksum ||
92			len(g.Archive.EffectiveValues) != 1 || g.Archive.EffectiveValues[0] != 5 {
93			t.Fatalf("upstream archive altered: %+v", g)
94		}
95		diskAfter, err := os.ReadFile(filepath.Join(dir, jobFileName(up.ID)))
96		if err != nil {
97			t.Fatal(err)
98		}
99		if string(diskAfter) != string(diskBefore) {
100			t.Fatalf("upstream on-disk record changed despite rejected submit:\nbefore=%s\nafter=%s",
101				diskBefore, diskAfter)
102		}
103	}
104	
105	// 目录暂时不可写、临时记录无法创建时，合法的带依赖提交必须返回实际保存
106	// 错误而非已接受作业；写入恢复后用同一提交人+请求号原样重试仍被接受，
107	// 并按现有规则把上游总和追加到最初指定的整数次序之后计算。
108	func TestSubmitTempRecordCannotCreateRejectsAndAllowsIdenticalRetry(t *testing.T) {
109		dir := t.TempDir()
110		s, err := Open(dir, WithClock(newManualClock()))
111		if err != nil {
112			t.Fatal(err)
113		}
114		t.Cleanup(func() { _ = s.Close() })
115		up := submitSumFiveUpstream(t, s)
116		upDisk, err := os.ReadFile(filepath.Join(dir, jobFileName(up.ID)))
117		if err != nil {
118			t.Fatal(err)
119		}
120	
121		req := SubmitRequest{
122			Submitter: "alice", RequestID: "retry-k",
123			Values: []int64{2, -3}, Seed: 7,
124			Dependencies: []uint64{up.ID},
125		}
126		rejectedID := up.ID + 1 // 若被接受，它应取得的作业号
127	
128		// 目录不可写：临时记录无法创建。
129		makeArchiveReadOnly(t, dir)
130		j, err := s.Submit(req)
131		if !errors.Is(err, fs.ErrPermission) || j != nil {
132			t.Fatalf("submit while temp cannot be created: job=%+v err=%v, want permission error and nil job", j, err)
133		}
134		// 第一次未被接受：紧接着的原样重试同样必须返回实际保存错误，而不是命中
135		// “已登记请求号”的幂等返回。
136		if j2, err2 := s.Submit(req); !errors.Is(err2, fs.ErrPermission) || j2 != nil {
137			t.Fatalf("repeat submit while unwritable: job=%+v err=%v, want permission error and nil job", j2, err2)
138		}
139		makeArchiveWritable(t, dir)
140	
141		// 未接受请求在任何视角都不可见：按提交人列举只有上游，按作业号查不到，
142		// 目录里没有对应正式记录，也没有残留临时文件。
143		list, err := s.List("alice", time.Time{}, time.Time{})
144		if err != nil {
145			t.Fatal(err)
146		}
147		if len(list) != 1 || list[0].ID != up.ID {
148			t.Fatalf("rejected submit visible via List: %v", ids(list))
149		}
150		if _, err := s.Get(rejectedID); !errors.Is(err, ErrNotFound) {
151			t.Fatalf("rejected submit visible via Get: %v", err)
152		}
153		if _, err := os.Stat(filepath.Join(dir, jobFileName(rejectedID))); !os.IsNotExist(err) {
154			t.Fatalf("formal record of rejected submit exists: %v", err)
155		}
156		if countJobFiles(t, dir) != 1 || countTmpFiles(t, dir) != 0 {
157			t.Fatalf("directory must contain only the upstream formal record, files=%d tmps=%d",
158				countJobFiles(t, dir), countTmpFiles(t, dir))
159		}
160		// 内存中的幂等索引同样不能登记该请求号。
161		s.mu.Lock()
162		_, claimed := s.idem[idemIdentity{"alice", "retry-k"}]
163		nextID := s.nextID
164		s.mu.Unlock()
165		if claimed {
166			t.Fatal("request id registered despite save failure")
167		}
168		if nextID != rejectedID {
169			t.Fatalf("nextID=%d, rejected submit must not consume job id %d", nextID, rejectedID)
170		}
171		assertUpstreamUnchanged(t, dir, s, up, upDisk)
172	
173		// 写入恢复后原样重试：同一提交人+请求号被当作全新请求接受，取得未被
174		// 占用的下一个作业号，仍使用最初指定的整数次序、种子与依赖。
175		again := mustSubmit(t, s, req)
176		if again.ID != rejectedID {
177			t.Fatalf("identical retry got id=%d, want unconsumed %d", again.ID, rejectedID)
178		}
179		if again.RequestID != "retry-k" || again.Seed != 7 ||
180			len(again.Values) != 2 || again.Values[0] != 2 || again.Values[1] != -3 ||
181			len(again.Dependencies) != 1 || again.Dependencies[0] != up.ID {
182			t.Fatalf("identical retry must keep original params/deps/order: %+v", again)
183		}
184		done := waitStatus(t, s, again.ID, StatusSucceeded)
185		// 实际输入 [2,-3] 后按现有规则追加上游总和 5：[2,-3,5]，总和 4、平方和 38。
186		wantEffective := []int64{2, -3, 5}
187		if len(done.Archive.EffectiveValues) != 3 {
188			t.Fatalf("effective=%v want %v", done.Archive.EffectiveValues, wantEffective)
189		}
190		for i, v := range wantEffective {
191			if done.Archive.EffectiveValues[i] != v {
192				t.Fatalf("effective=%v want %v", done.Archive.EffectiveValues, wantEffective)
193			}
194		}
195		if done.Archive.Sum != 4 || done.Archive.SumOfSquares != 38 {
196			t.Fatalf("retry results sum=%d sq=%d, want 4,38",
197				done.Archive.Sum, done.Archive.SumOfSquares)
198		}
199		// 上游结果保持不变。
200		assertUpstreamUnchanged(t, dir, s, up, upDisk)
201	}
202	
203	// 临时记录已写好却无法保存为正式记录（rename 被挡住）时，提交同样必须返回
204	// 实际保存错误。按题述序列：首次提交 [2,-3]、种子 7 并依赖总和为 5 的上游，
205	// 保存失败；写入条件恢复（含重开归档）后用同号改交 [4]、种子 9 且不带依赖，
206	// 必须按新内容接受——不报请求号冲突、不返回失败作业冒充已接受请求、不沿用
207	// 被拒绝请求的输入或依赖，最终归档总和 4、平方和 16，实际输入只有 [4]，
208	// 原上游结果保持不变。
209	func TestSubmitFormalRecordRenameFailsThenChangedContentAccepted(t *testing.T) {
210		dir := t.TempDir()
211		s, err := Open(dir)
212		if err != nil {
213			t.Fatal(err)
214		}
215		up := submitSumFiveUpstream(t, s)
216		upDisk, err := os.ReadFile(filepath.Join(dir, jobFileName(up.ID)))
217		if err != nil {
218			t.Fatal(err)
219		}
220		rejectedID := up.ID + 1
221	
222		first := SubmitRequest{
223			Submitter: "alice", RequestID: "change-k",
224			Values: []int64{2, -3}, Seed: 7,
225			Dependencies: []uint64{up.ID},
226		}
227		// 目标正式记录路径被非空目录挡住：临时文件可创建可写盘，但 rename 失败。
228		unblock := blockRenameWithDir(t, dir, rejectedID)
229		j, err := s.Submit(first)
230		if !isRenameBlockedError(err) || j != nil {
231			t.Fatalf("submit while formal record cannot be saved: job=%+v err=%v, want actual save error and nil job", j, err)
232		}
233		unblock()
234	
235		// 失败提交不留任何“已接受作业”痕迹。
236		list, _ := s.List("alice", time.Time{}, time.Time{})
237		if len(list) != 1 || list[0].ID != up.ID {
238			t.Fatalf("rejected submit visible via List: %v", ids(list))
239		}
240		if _, err := s.Get(rejectedID); !errors.Is(err, ErrNotFound) {
241			t.Fatalf("rejected submit visible via Get: %v", err)
242		}
243		if countJobFiles(t, dir) != 1 || countTmpFiles(t, dir) != 0 {
244			t.Fatalf("directory must keep only upstream formal record, files=%d tmps=%d",
245				countJobFiles(t, dir), countTmpFiles(t, dir))
246		}
247		s.mu.Lock()
248		_, claimed := s.idem[idemIdentity{"alice", "change-k"}]
249		nextID := s.nextID
250		s.mu.Unlock()
251		if claimed || nextID != rejectedID {
252			t.Fatalf("rejected submit consumed registration: claimed=%v nextID=%d want %d",
253				claimed, nextID, rejectedID)
254		}
255		assertUpstreamUnchanged(t, dir, s, up, upDisk)
256	
257		// “写入条件恢复”也包括关闭后重新打开同一目录：被拒绝请求没有留下任何
258		// 会被恢复成已接受作业的记录，幂等号也未跨重开生效。
259		if err := s.Close(); err != nil {
260			t.Fatal(err)
261		}
262		s2, err := Open(dir)
263		if err != nil {
264			t.Fatal(err)
265		}
266		t.Cleanup(func() { _ = s2.Close() })
267		if _, err := s2.Get(rejectedID); !errors.Is(err, ErrNotFound) {
268			t.Fatalf("rejected submit resurfaced after reopen: %v", err)
269		}
270		assertUpstreamUnchanged(t, dir, s2, up, upDisk)
271	
272		// 同号改交另一份合法内容：作为新作业接受，不能报请求号冲突。
273		changed := SubmitRequest{
274			Submitter: "alice", RequestID: "change-k",
275			Values: []int64{4}, Seed: 9,
276		}
277		got, err := s2.Submit(changed)
278		if err != nil {
279			t.Fatalf("changed-content retry after rejected submit: %v", err)
280		}
281		if got == nil || got.ID != rejectedID {
282			t.Fatalf("changed-content retry job=%+v, want newly accepted id %d", got, rejectedID)
283		}
284		if got.Status == StatusFailed {
285			t.Fatalf("changed-content retry must not return a failed job posing as accepted: %+v", got)
286		}
287		done := waitStatus(t, s2, got.ID, StatusSucceeded)
288		// 必须按新内容接受：种子 9、无依赖、实际输入只有 [4]，绝不沿用被拒绝
289		// 请求的 [2,-3] 或对上游总和 5 的依赖。
290		if done.Seed != 9 || done.RequestID != "change-k" {
291			t.Fatalf("accepted retry params wrong: %+v", done)
292		}
293		if len(done.Dependencies) != 0 || done.HasDependency || done.DependencyID != 0 {
294			t.Fatalf("accepted retry must carry no dependency from rejected request: %+v", done)
295		}
296		if len(done.Values) != 1 || done.Values[0] != 4 {
297			t.Fatalf("accepted retry original values=%v want [4]", done.Values)
298		}
299		if len(done.Archive.EffectiveValues) != 1 || done.Archive.EffectiveValues[0] != 4 {
300			t.Fatalf("accepted retry effective=%v want [4] (must not append upstream sum 5)",
301				done.Archive.EffectiveValues)
302		}
303		if done.Archive.Sum != 4 || done.Archive.SumOfSquares != 16 {
304			t.Fatalf("accepted retry results sum=%d sq=%d, want 4,16",
305				done.Archive.Sum, done.Archive.SumOfSquares)
306		}
307		assertUpstreamUnchanged(t, dir, s2, up, upDisk)
308	
309		// 同号请求真正被接受以后，现有幂等规则才生效：
310		// 相同内容再次提交返回该作业当前详情；改变内容返回冲突并保留原记录。
311		replay, err := s2.Submit(changed)
312		if err != nil || replay == nil || replay.ID != got.ID || replay.Status != StatusSucceeded {
313			t.Fatalf("idempotent replay after acceptance: job=%+v err=%v", replay, err)
314		}
315		conflictJob, err := s2.Submit(SubmitRequest{
316			Submitter: "alice", RequestID: "change-k",
317			Values: []int64{2, -3}, Seed: 7,
318			Dependencies: []uint64{up.ID},
319		})
320		if !errors.Is(err, ErrIdempotencyConflict) || conflictJob == nil || conflictJob.ID != got.ID {
321			t.Fatalf("changed content after acceptance must conflict: job=%+v err=%v", conflictJob, err)
322		}
323		kept := waitStatus(t, s2, got.ID, StatusSucceeded)
324		if kept.Archive.Sum != 4 || kept.Archive.SumOfSquares != 16 || kept.Seed != 9 ||
325			len(kept.Dependencies) != 0 || len(kept.Archive.EffectiveValues) != 1 {
326			t.Fatalf("accepted record must be preserved by conflict: %+v", kept)
327		}
328		assertUpstreamUnchanged(t, dir, s2, up, upDisk)
329	}
330	
331	// 已接受作业后来计算失败与“首份记录保存失败、请求未被接受”是两回事：
332	// 终态为失败的作业仍保留自己的作业号与请求号，相同内容重放返回它本身，
333	// 改变内容按冲突处理并保留失败记录——不能把失败终态当作允许重新创建作业
334	// 的理由（重开归档后同样如此）。
335	func TestAcceptedThenFailedJobKeepsIDAndRequestIDAcrossReplay(t *testing.T) {
336		dir := t.TempDir()
337		s, err := Open(dir)
338		if err != nil {
339			t.Fatal(err)
340		}
341		big := int64(3037000500)
342		req := SubmitRequest{Submitter: "a", RequestID: "k", Values: []int64{big}}
343		j := mustSubmit(t, s, req)
344		failed := waitStatus(t, s, j.ID, StatusFailed)
345		if !strings.Contains(failed.FailureReason, "平方和") || failed.Archive != nil {
346			t.Fatalf("accepted job should fail by overflow with no archive: %+v", failed)
347		}
348		if failed.ID != j.ID || failed.RequestID != "k" {
349			t.Fatalf("failed terminal job must keep own id and request id: %+v", failed)
350		}
351	
352		// 相同内容再次提交：返回该失败作业本身，无错误，不重建作业、不重新排队。
353		replay, err := s.Submit(req)
354		if err != nil || replay == nil || replay.ID != j.ID || replay.Status != StatusFailed {
355			t.Fatalf("replay of accepted-then-failed job must return the same job: %+v err=%v", replay, err)
356		}
357		// 改变内容：幂等冲突，同时返回原失败作业，原因保持不变。
358		cj, err := s.Submit(SubmitRequest{
359			Submitter: "a", RequestID: "k", Values: []int64{1, 2}, Seed: 0,
360		})
361		if !errors.Is(err, ErrIdempotencyConflict) || cj == nil || cj.ID != j.ID {
362			t.Fatalf("changed content for failed accepted job must conflict: %+v err=%v", cj, err)
363		}
364		if cj.Status != StatusFailed || cj.FailureReason != failed.FailureReason || cj.Archive != nil {
365			t.Fatalf("failed record altered by conflict attempt: %+v", cj)
366		}
367		if countJobFiles(t, dir) != 1 {
368			t.Fatalf("replay/conflict must not create records: %d files", countJobFiles(t, dir))
369		}
370	
371		// 重开归档后仍保留自己的作业号与请求号，重放依旧指向它，不允许重建。
372		if err := s.Close(); err != nil {
373			t.Fatal(err)
374		}
375		s2, err := Open(dir)
376		if err != nil {
377			t.Fatal(err)
378		}
379		defer s2.Close()
380		g, _ := s2.Get(j.ID)
381		if g.Status != StatusFailed || g.RequestID != "k" || g.FailureReason != failed.FailureReason {
382			t.Fatalf("failed accepted job after reopen: %+v", g)
383		}
384		r2, err := s2.Submit(req)
385		if err != nil || r2 == nil || r2.ID != j.ID || r2.Status != StatusFailed {
386			t.Fatalf("replay after reopen must keep the failed job, no recreation: %+v err=%v", r2, err)
387		}
388	}
