11	// writeNamedSyntheticRecord 用任意文件名写一条作业记录，用于构造正常运行
12	// 不会产生的形态：多份记录共享同一作业号但文件名不同。
13	func writeNamedSyntheticRecord(t *testing.T, dir, name string, j *storedJob) {
14		t.Helper()
15		data, err := encodeRecord(j)
16		if err != nil {
17			t.Fatal(err)
18		}
19		if err := writeFileAtomic(dir, name, data, 0o600); err != nil {
20			t.Fatal(err)
21		}
22	}
