24	func snapshotDir(t *testing.T, dir string) map[string][]byte {
25		t.Helper()
26		entries, err := os.ReadDir(dir)
27		if err != nil {
28			t.Fatal(err)
29		}
30		out := make(map[string][]byte)
31		for _, e := range entries {
32			if e.IsDir() {
33				continue
34			}
35			b, err := os.ReadFile(filepath.Join(dir, e.Name()))
36			if err != nil {
37				t.Fatal(err)
38			}
39			out[e.Name()] = b
40		}
41		return out
42	}
