44	func assertDirUnchanged(t *testing.T, dir string, before map[string][]byte) {
45		t.Helper()
46		after := snapshotDir(t, dir)
47		if len(after) != len(before) {
48			t.Fatalf("目录条目变化: before=%d after=%d", len(before), len(after))
49		}
50		for name, want := range before {
51			got, ok := after[name]
52			if !ok {
53				t.Fatalf("原有记录文件 %s 在打开失败后消失", name)
54			}
55			if string(got) != string(want) {
56				t.Fatalf("记录文件 %s 在重复作业号打开失败后被改写", name)
57			}
58		}
59		for name := range after {
60			if _, ok := before[name]; !ok {
61				t.Fatalf("打开失败后目录中多出文件 %s", name)
62			}
63		}
64	}
