96	// TestOpenRejectsDuplicateJobID 两份可正常解析、版本与状态合法的记录顶层
97	// 保存同一作业号时，Open 必须失败、返回非空错误且归档对象为 nil；错误须
98	// 说明重复作业号、包含该作业号与两份冲突记录的文件名。
99	func TestOpenRejectsDuplicateJobID(t *testing.T) {
100		dir := t.TempDir()
101		base := time.Date(2026, 4, 1, 8, 0, 0, 0, time.UTC)
102		name1 := jobFileName(7)
103		name2 := "job-00000000000000000007-copy.json"
104		writeNamedSyntheticRecord(t, dir, name1,
105			queuedStoredJob(7, "alice", []int64{1, 2}, base))
106		writeNamedSyntheticRecord(t, dir, name2,
107			queuedStoredJob(7, "bob", []int64{3, 4}, base.Add(time.Second)))
108	
109		s, err := Open(dir)
110		if err == nil {
111			if s != nil {
112				_ = s.Close()
113			}
114			t.Fatal("Open 必须在重复作业号时失败")
115		}
116		if s != nil {
117			t.Fatalf("重复作业号冲突时归档对象必须为 nil，得到 %#v", s)
118		}
119		if !strings.Contains(err.Error(), "重复作业号") {
120			t.Fatalf("错误必须明确说明存在重复作业号: %v", err)
121		}
122		if !strings.Contains(err.Error(), "7") {
123			t.Fatalf("错误必须包含重复的作业号 7: %v", err)
124		}
125		if !strings.Contains(err.Error(), name1) || !strings.Contains(err.Error(), name2) {
126			t.Fatalf("错误必须包含两份冲突记录的文件名 %s、%s: %v", name1, name2, err)
127		}
128	}
