339			queuedStoredJob(5, "a", []int64{9}, base.Add(7*time.Second)))
340		dupName := "job-00000000000000000005-dup.json"
341		writeNamedSyntheticRecord(t, dir, dupName,
342			queuedStoredJob(5, "b", []int64{10}, base.Add(8*time.Second)))
343	
344		if s, err := Open(dir); err == nil {
345			_ = s.Close()
346			t.Fatal("处理冲突前打开必须失败")
347		}
348		// 调用方自行删除一份冲突记录。
349		if err := os.Remove(filepath.Join(dir, dupName)); err != nil {
350			t.Fatal(err)
351		}
352	
353		s, err := Open(dir)
354		if err != nil {
355			t.Fatalf("冲突解决后再次打开应按既有规则恢复: %v", err)
356		}
357		defer s.Close()
358	
359		j1, _ := s.Get(1)
360		if j1.Status != StatusFailed || !strings.Contains(j1.FailureReason, "中断") {
361			t.Fatalf("作业 1 应按既有规则改判中断失败: %s %q", j1.Status, j1.FailureReason)
362		}
363		j2 := waitStatus(t, s, 2, StatusFailed)
364		if j2.BlockerID != 1 {
365			t.Fatalf("作业 2 应沿链条保留根因 1，得到 %d", j2.BlockerID)
366		}
367		j3, _ := s.Get(3)
368		if j3.Status != StatusSucceeded || j3.Archive == nil || j3.Archive.Checksum != wantChecksum {
369			t.Fatalf("合法成功归档应原样保留: %+v", j3)
370		}
371		j5 := waitStatus(t, s, 5, StatusSucceeded)
372		if j5.Archive == nil || j5.Archive.Sum != 9 {
373			t.Fatalf("保留的作业 5 应正常计算完成: %+v", j5)
374		}
375	}
