453		t.Run("损坏记录排在冲突之前时先报损坏", func(t *testing.T) {
454			dir := t.TempDir()
455			// job-...01.json 损坏，文件名排序早于作业 3 的冲突对。
456			if err := os.WriteFile(filepath.Join(dir, jobFileName(1)),
457				[]byte("{not json"), 0o600); err != nil {
458				t.Fatal(err)
459			}
460			writeNamedSyntheticRecord(t, dir, jobFileName(3),
461				queuedStoredJob(3, "a", []int64{1}, base))
462			writeNamedSyntheticRecord(t, dir, "job-00000000000000000003-dup.json",
463				queuedStoredJob(3, "b", []int64{2}, base))
464			s, err := Open(dir)
465			if err == nil {
466				_ = s.Close()
467				t.Fatal("必须打开失败")
468			}
469			if s != nil || !strings.Contains(err.Error(), "损坏") {
470				t.Fatalf("先读到损坏记录时应保留原有损坏错误: %v", err)
471			}
472		})
473	
474		t.Run("同目录另有损坏记录时保留原有损坏错误", func(t *testing.T) {
475			// 重复作业号检查只在全部记录都可正常解析、版本及状态合法时生效；
476			// 损坏记录即使文件名排在冲突对之后，其原有打开错误仍然有效。
477			dir := t.TempDir()
478			writeNamedSyntheticRecord(t, dir, "job-00000000000000000001-a.json",
479				queuedStoredJob(1, "a", []int64{1}, base))
480			writeNamedSyntheticRecord(t, dir, jobFileName(1),
481				queuedStoredJob(1, "b", []int64{2}, base))
482			if err := os.WriteFile(filepath.Join(dir, jobFileName(2)),
483				[]byte("{not json"), 0o600); err != nil {
484				t.Fatal(err)
485			}
486			before := snapshotDir(t, dir)
487			s, err := Open(dir)
488			if err == nil {
489				_ = s.Close()
490				t.Fatal("必须打开失败")
491			}
492			if s != nil || !strings.Contains(err.Error(), "损坏") {
493				t.Fatalf("存在损坏记录时应保留原有的损坏错误，而非重复作业号错误: %v", err)
494			}
495			// 解析阶段失败同样不允许改写目录内任何记录。
496			assertDirUnchanged(t, dir, before)
497		})
498	}
